<script setup lang="ts">
type Site={id:string;name:string;origin:string;ga4_property:string;search_property:string;ahrefs_url:string;plausible_url:string;clarity_url:string}
const sites=ref<Site[]>([]),siteId=ref('mc-studio'),days=ref(28),report=ref<any>(null),loading=ref(false),busy=ref(false),error=ref(''),editing=ref(false),tab=ref('overview')
const googleConfigured=ref(false),cruxConfigured=ref(false)
const site=computed(()=>sites.value.find(s=>s.id===siteId.value))
const blank=()=>({id:'',name:'',origin:'',ga4_property:'',search_property:'',ahrefs_url:'',plausible_url:'',clarity_url:''})
const form=reactive(blank())
const fmt=(value:unknown)=>value===null||value===undefined?'—':Number(value).toLocaleString('fr-FR',{maximumFractionDigits:2})
const date=(value:string)=>value?new Date(value+'T12:00:00Z').toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'}):''
const delta=(current:number|undefined,previous:number|undefined)=>current===undefined||previous===undefined?'Comparaison indisponible':previous===0?(current===0?'Stable · période précédente':'Pas de base de comparaison'):`${current>=previous?'+':''}${((current-previous)/previous*100).toFixed(1)} % · période précédente`
const fail=(e:any)=>{error.value=e?.data?.statusMessage||'Impossible de charger le tableau de bord.'}
async function loadSites(){const data=await $fetch<{sites:Site[];googleConfigured:boolean;cruxConfigured:boolean}>('/api/portal/admin/growth/sites');sites.value=data.sites;googleConfigured.value=data.googleConfigured;cruxConfigured.value=data.cruxConfigured}
let serial=0
async function load(){const request=++serial;loading.value=true;error.value='';report.value=null;try{const data=await $fetch('/api/portal/admin/growth/report',{query:{siteId:siteId.value,days:days.value}});if(request===serial)report.value=data}catch(e){if(request===serial)fail(e)}finally{if(request===serial)loading.value=false}}
onMounted(async()=>{try{await loadSites();await load()}catch(e){fail(e)}})
watch([siteId,days],load)
function configure(add=false){Object.assign(form,blank(),add?{}:site.value||{});editing.value=true;error.value=''}
async function save(){busy.value=true;error.value='';try{const result=await $fetch<{id:string}>('/api/portal/admin/growth/sites',{method:'POST',body:{...form}});await loadSites();editing.value=false;if(siteId.value===result.id)await load();else siteId.value=result.id}catch(e){fail(e)}finally{busy.value=false}}
const kpis=computed(()=>[
 {label:'Visiteurs actifs',source:'GA4',value:report.value?.ga4.current?.activeUsers,previous:report.value?.ga4.previous?.activeUsers,definition:'Utilisateurs actifs distincts sur la période, dans le fuseau de la propriété GA4.'},
 {label:'Sessions',source:'GA4',value:report.value?.ga4.current?.sessions,previous:report.value?.ga4.previous?.sessions,definition:'Sessions mesurées par Google Analytics sur cette propriété.'},
 {label:'Événements clés',source:'GA4',value:report.value?.ga4.current?.keyEvents,previous:report.value?.ga4.previous?.keyEvents,definition:'Événements marqués comme clés dans GA4. Ce total ne correspond pas nécessairement à des prospects ou des ventes.'},
 {label:'Clics organiques',source:'Search Console',value:report.value?.search.current?.clicks,previous:report.value?.search.previous?.clicks,definition:'Clics depuis la recherche Google Web. Données finalisées Search Console.'}
])
const actions=computed(()=>{
 const rows:{priority:number;title:string;detail:string;source:string;setup?:boolean}[]=[]
 if(report.value?.ga4.state!=='connected')rows.push({priority:1,title:'Connecter Google Analytics',detail:'Mesurer les visites et les événements clés avant d’évaluer la conversion.',source:'Configuration',setup:true})
 if(report.value?.search.state!=='connected')rows.push({priority:2,title:'Connecter Search Console',detail:'Faire remonter les requêtes Google, les clics et les impressions.',source:'Configuration',setup:true})
 for(const m of report.value?.vitals.metrics||[])if(m.value!==null&&Number(m.value)>m.good)rows.push({priority:1,title:`Améliorer ${m.name}`,detail:`Le 75e percentile mobile est de ${fmt(m.value)} ${m.unit}, au-dessus du seuil de bon confort (${fmt(m.good)} ${m.unit}).`,source:'CrUX · seuil Google'})
 const ga=report.value?.ga4
 if(ga?.previous?.sessions>0 && ga.current.sessions<ga.previous.sessions*.8)rows.push({priority:2,title:'Examiner la baisse de trafic',detail:'Les sessions baissent de plus de 20 % par rapport à la période précédente de même durée. Examiner les canaux avant de conclure.',source:'GA4 · règle de suivi 20 %'})
 if(ga?.current?.sessions>0 && ga.current.keyEvents===0)rows.push({priority:2,title:'Vérifier le suivi des événements clés',detail:'Des sessions sont enregistrées, mais aucun événement clé. Vérifier leur configuration dans GA4.',source:'GA4'})
 if(report.value?.vitals.state==='setup')rows.push({priority:3,title:'Activer les Core Web Vitals',detail:'Suivre le chargement, la réactivité et la stabilité sur mobile.',source:'Configuration',setup:true})
 return rows.sort((a,b)=>a.priority-b.priority)
})
const sourceRows=computed(()=>[
 {name:'Google Analytics 4',detail:'Trafic, canaux et événements clés',state:report.value?.ga4.state||'setup',message:report.value?.ga4.message,url:'https://analytics.google.com/'},
 {name:'Search Console',detail:'Visibilité dans Google',state:report.value?.search.state||'setup',message:report.value?.search.message,url:'https://search.google.com/search-console'},
 {name:'Core Web Vitals',detail:'Mesures réelles Chrome · mobile',state:report.value?.vitals.state||'setup',message:report.value?.vitals.message,url:'https://pagespeed.web.dev/'},
 {name:'Ahrefs',detail:'Backlinks et recherche SEO',state:site.value?.ahrefs_url?'link':'setup',url:site.value?.ahrefs_url},
 {name:'Plausible',detail:'Rapport de trafic complémentaire',state:site.value?.plausible_url?'link':'setup',url:site.value?.plausible_url},
 {name:'Microsoft Clarity',detail:'Heatmaps et enregistrements',state:site.value?.clarity_url?'link':'setup',url:site.value?.clarity_url}
])
const status:Record<string,string>={connected:'Données disponibles',setup:'À connecter',error:'Accès à vérifier',empty:'Données insuffisantes',link:'Lien configuré'}
const sessions=computed(()=>(report.value?.ga4.daily||[]).map((r:any)=>({date:r.date,value:r.sessions})))
const clicks=computed(()=>(report.value?.search.daily||[]).map((r:any)=>({date:r.date,value:r.clicks})))
const collectionDate=(v:any)=>v?`${String(v.day).padStart(2,'0')}/${String(v.month).padStart(2,'0')}/${v.year}`:''
</script>
<template>
 <section class="growth">
  <header class="growth-head"><div><h1>Croissance & performance</h1><p>MC Studio et vos sites clients.</p></div><div class="controls"><label class="sr-only" for="growth-site">Site suivi</label><select id="growth-site" v-model="siteId"><option v-for="s in sites" :key="s.id" :value="s.id">{{s.name}}</option></select><button @click="configure(true)">+ Ajouter un site</button><button class="primary" :disabled="!site" @click="configure()"><UIcon name="i-tabler-plug"/>Configurer les sources</button></div></header>
  <p v-if="error" role="alert" class="notice">{{error}}</p>
  <form v-if="editing" class="source-form" @submit.prevent="save"><header><h2>{{form.id?'Sources de '+form.name:'Nouveau site à suivre'}}</h2><button type="button" :disabled="busy" @click="editing=false">Fermer</button></header><div class="fields"><label>Nom du site<input v-model="form.name" required maxlength="100" placeholder="Ex. Souji Nova"></label><label>Adresse du site<input v-model="form.origin" required type="url" placeholder="https://www.exemple.fr"></label><label>Identifiant de propriété GA4<input v-model="form.ga4_property" inputmode="numeric" pattern="[0-9]*" placeholder="123456789"><small>Identifiant numérique de la propriété, pas l’identifiant G-…</small></label><label>Propriété Search Console<input v-model="form.search_property" placeholder="sc-domain:exemple.fr"><small>Ou l’URL exacte de la propriété, avec sa barre finale.</small></label><label>Lien du rapport Ahrefs<input v-model="form.ahrefs_url" type="url" placeholder="https://app.ahrefs.com/…"></label><label>Lien du rapport Plausible<input v-model="form.plausible_url" type="url" placeholder="https://plausible.io/…"></label><label>Lien du projet Clarity<input v-model="form.clarity_url" type="url" placeholder="https://clarity.microsoft.com/…"></label></div><div class="setup-status"><p>Compte de service Google : <strong>{{googleConfigured?'configuré sur le serveur':'à configurer sur le serveur'}}</strong></p><p>Clé Chrome UX Report : <strong>{{cruxConfigured?'configurée sur le serveur':'à configurer sur le serveur'}}</strong></p><details><summary>Comment activer les sources ?</summary><p>Google : activer les API Analytics Data et Search Console, donner au compte de service un accès de lecture à chaque propriété, puis définir GOOGLE_SERVICE_ACCOUNT_JSON dans l’environnement privé du serveur.</p><p>Core Web Vitals : activer Chrome UX Report et définir CRUX_API_KEY sur le serveur. Redémarrer le serveur après configuration.</p><p>Ahrefs, Plausible et Clarity : ajoutez les liens de vos rapports. Ces trois outils s’ouvrent dans leur application ; leurs données ne sont pas synchronisées ici.</p></details></div><button class="primary" :disabled="busy">{{busy?'Enregistrement…':'Enregistrer les sources'}}</button></form>
  <div class="view-bar"><nav aria-label="Rapports de croissance"><button v-for="t in [{id:'overview',name:'Vue d’ensemble'},{id:'seo',name:'Recherche Google'},{id:'sources',name:'Sources'}]" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{t.name}}</button></nav><div class="controls"><label class="sr-only" for="growth-period">Durée du rapport</label><select id="growth-period" v-model="days"><option :value="7">7 jours</option><option :value="28">28 jours</option><option :value="90">90 jours</option></select><button :disabled="loading" @click="load"><UIcon name="i-tabler-refresh"/>Actualiser</button></div></div>
  <div v-if="report" class="period-note"><span>{{site?.origin}} · {{date(report.period.start)}} — {{date(report.period.end)}}</span><span>Comparaison : {{date(report.period.previousStart)}} — {{date(report.period.previousEnd)}}</span></div>
  <p v-if="loading" class="loading" role="status">Chargement des sources…</p>
  <template v-else-if="report">
   <template v-if="tab==='overview'">
    <div class="kpis"><article v-for="k in kpis" :key="k.label"><div><span :title="k.definition">{{k.label}} ⓘ</span><small>{{k.source}}</small></div><strong>{{fmt(k.value)}}</strong><p>{{k.value===undefined?'Source à connecter ou indisponible':delta(k.value,k.previous)}}</p></article></div>
    <div class="dashboard-grid"><section class="panel traffic"><header><div><h2>Sessions au fil des jours</h2><p>Google Analytics 4 · {{report.ga4.timeZone||'période sélectionnée'}}</p></div><span class="source-badge">GA4</span></header><PortalGrowthChart v-if="sessions.length" :rows="sessions" label="sessions" :start="report.period.start" :end="report.period.end"/><div v-else class="empty-chart"><UIcon name="i-tabler-chart-histogram"/><h3>{{report.ga4.state==='connected'?'Aucune session sur cette période':'Votre trafic apparaîtra ici'}}</h3><p>{{report.ga4.message||'Choisissez une autre période pour explorer le trafic.'}}</p><button v-if="report.ga4.state!=='connected'" @click="configure()">Configurer GA4 ↗</button></div></section>
    <section class="panel"><header><div><h2>Canaux d’acquisition</h2><p>Sessions par canal · GA4</p></div></header><div v-if="report.ga4.channels?.length" class="bar-list"><div v-for="c in report.ga4.channels" :key="c.name"><div><span>{{c.name}}</span><strong>{{fmt(c.value)}}</strong></div><span class="bar"><i :style="{width:(c.value/Math.max(1,...report.ga4.channels.map((x:any)=>x.value))*100)+'%'}"/></span></div></div><div v-else class="empty-small"><UIcon name="i-tabler-route"/><p>{{report.ga4.state==='connected'?'Aucun canal sur cette période.':'Connectez GA4 pour identifier les sources de trafic.'}}</p></div></section>
    <section class="panel priorities"><header><div><h2>À faire en priorité</h2><p>Configuration et signaux observés</p></div><span class="count">{{actions.length}}</span></header><ol v-if="actions.length"><li v-for="(a,index) in actions" :key="a.title"><span class="rank">{{index+1}}</span><div><h3>{{a.title}}</h3><p>{{a.detail}}</p><small>{{a.source}}</small></div><button v-if="a.setup" aria-label="Configurer les sources" @click="configure()">↗</button></li></ol><p v-else class="empty-small">Aucun signal ne déclenche les règles de suivi actuelles.</p><details class="rules"><summary>Comment les priorités sont-elles définies ?</summary><p>Ordre : accès GA4 et seuils Core Web Vitals dépassés, puis accès Search Console et baisse des sessions supérieure à 20 %, puis configuration CrUX. Ce sont des points à examiner, sans diagnostic automatique de leur cause.</p></details></section>
    <section class="panel"><header><div><h2>Core Web Vitals</h2><p>Visiteurs Chrome · mobile · 75e percentile</p></div><span class="source-badge">CrUX</span></header><div v-if="report.vitals.metrics" class="vitals"><div v-for="m in report.vitals.metrics" :key="m.name"><div><strong>{{m.name}}</strong><span>{{m.label}}</span></div><b>{{fmt(m.value)}} <small>{{m.unit}}</small></b><span class="source-badge">{{m.value===null?'Indisponible':Number(m.value)<=m.good?'Bon':'À améliorer'}}</span></div><p>Fenêtre CrUX : {{collectionDate(report.vitals.period?.firstDate)}} — {{collectionDate(report.vitals.period?.lastDate)}}. Cette fenêtre est indépendante du filtre du rapport.</p></div><div v-else class="empty-small"><UIcon name="i-tabler-gauge"/><p>{{report.vitals.message}}</p><button v-if="report.vitals.state==='setup'" @click="configure()">Configurer CrUX ↗</button></div></section>
    <section class="panel pages"><header><div><h2>Pages les plus vues</h2><p>10 premières pages · GA4</p></div></header><div v-if="report.ga4.pages?.length" class="table-wrap"><table><thead><tr><th>Page</th><th>Vues</th></tr></thead><tbody><tr v-for="p in report.ga4.pages" :key="p.name"><td>{{p.name}}</td><td>{{fmt(p.value)}}</td></tr></tbody></table></div><p v-else class="empty-small">{{report.ga4.state==='connected'?'Aucune page vue sur cette période.':'Les pages consultées apparaîtront après connexion de GA4.'}}</p></section>
    <section class="panel"><header><div><h2>Vos outils</h2><p>Accès aux rapports complémentaires</p></div></header><div class="tool-list"><article v-for="s in sourceRows.slice(3)" :key="s.name"><span><strong>{{s.name}}</strong><small>{{s.detail}}</small></span><a v-if="s.url" :href="s.url" target="_blank" rel="noopener noreferrer">Ouvrir ↗</a><button v-else @click="configure()">Ajouter le lien</button></article></div></section>
    </div>
   </template>
   <template v-else-if="tab==='seo'"><div class="kpis"><article v-for="m in [{key:'clicks',label:'Clics'},{key:'impressions',label:'Impressions'},{key:'ctr',label:'Taux de clics'},{key:'position',label:'Position moyenne'}]" :key="m.key"><div><span>{{m.label}}</span><small>Search Console</small></div><strong>{{report.search.current?.[m.key]===null||report.search.current?.[m.key]===undefined?'—':m.key==='ctr'?fmt(report.search.current[m.key]*100)+' %':fmt(report.search.current[m.key])}}</strong><p>{{m.key==='ctr'?'Clics ÷ impressions':m.key==='position'?'Position moyenne fournie par Google':'Recherche Google · Web'}}</p></article></div><section class="panel"><header><h2>Clics organiques au fil des jours</h2><span class="source-badge">Search Console</span></header><PortalGrowthChart v-if="clicks.length" :rows="clicks" label="clics" :start="report.period.start" :end="report.period.end"/><div v-else class="empty-chart"><UIcon name="i-tabler-search"/><h3>{{report.search.state==='connected'?'Aucun clic sur cette période':'Votre visibilité Google, au même endroit'}}</h3><p>{{report.search.message}}</p><button v-if="report.search.state!=='connected'" @click="configure()">Configurer Search Console ↗</button></div></section><section class="panel queries"><header><div><h2>Requêtes les plus cliquées</h2><p>10 premières requêtes disponibles ; les requêtes anonymisées ne sont pas affichées par Google.</p></div></header><div v-if="report.search.queries?.length" class="table-wrap"><table><thead><tr><th>Requête</th><th>Clics</th><th>Impressions</th><th>CTR</th><th>Position</th></tr></thead><tbody><tr v-for="q in report.search.queries" :key="q.name"><td>{{q.name}}</td><td>{{fmt(q.clicks)}}</td><td>{{fmt(q.impressions)}}</td><td>{{fmt(q.ctr*100)}} %</td><td>{{fmt(q.position)}}</td></tr></tbody></table></div><p v-else class="empty-small">Aucune requête disponible.</p></section></template>
   <section v-else class="panel"><header><div><h2>Sources de {{site?.name}}</h2><p>État des connexions et accès aux outils</p></div><button @click="configure()">Modifier</button></header><div class="source-list"><article v-for="s in sourceRows" :key="s.name"><div><h3>{{s.name}}</h3><p>{{s.detail}}</p><small v-if="s.message">{{s.message}}</small></div><span class="source-badge">{{status[s.state]}}</span><a v-if="s.url" :href="s.url" target="_blank" rel="noopener noreferrer">Ouvrir ↗</a></article></div></section>
   <footer class="freshness">Consulté le {{new Date(report.fetchedAt).toLocaleString('fr-FR')}} · Cache de 5 minutes. Les rapports s’arrêtent à J−3 pour limiter les données provisoires. GA4 utilise le fuseau de la propriété ; Search Console utilise l’heure du Pacifique.<span v-if="report.ga4.thresholded"> Google applique des seuils de confidentialité à ce rapport.</span></footer>
  </template>
 </section>
</template>
<style scoped>
.growth{color:var(--portal-text, #e6e6e6);font:12px/1.5 Inter,Arial,sans-serif;max-width:1600px;margin:auto}.growth *{box-sizing:border-box}.growth h1,.growth h2,.growth h3,.growth p{margin:0}.growth h1{background:none;-webkit-text-fill-color:var(--portal-text, #eee);color:var(--portal-text, #eee);font-size:23px;letter-spacing:-.6px;font-weight:500;margin:3px 0 5px}.growth h2{font-size:13px;font-weight:500}.growth h3{font-size:12px;font-weight:500}.growth p{color:var(--portal-muted, #888);font-size:11px}.eyebrow{font-size:9px;letter-spacing:1.4px;color:var(--portal-muted, #777)}.growth-head{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:26px}.controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.growth button,.growth select,.growth input{font:inherit;color:var(--portal-text, #ddd)}.growth button,.growth select,.growth a{border:1px solid var(--portal-line, #3a3a3a);border-radius:99px;padding:7px 12px;background:var(--portal-raised, #222);cursor:pointer;font-size:11px;display:inline-flex;align-items:center;gap:7px;text-decoration:none;color:var(--portal-text, #ddd)}.growth button:hover,.growth a:hover{background:var(--portal-raised, #303030)}.growth button:disabled{opacity:.5;cursor:default}.growth .primary{background:linear-gradient(#d4ad5b,#a97c32);border-color:#e3c574;color:white}.growth:focus-visible{outline:2px solid var(--portal-line, #ddd);outline-offset:3px}.view-bar{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--portal-line, #333);margin-bottom:15px;gap:14px}.view-bar nav{display:flex;gap:24px}.view-bar nav button{border:0;border-bottom:2px solid transparent;background:none;border-radius:0;padding:14px 0;color:var(--portal-muted, #888)}.view-bar nav button.active{color:var(--portal-text, #eee);border-color:var(--portal-line, #eee)}.period-note{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:10px;color:var(--portal-muted, #777);margin:15px 0 20px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--portal-line, #333);border-radius:8px;overflow:hidden;margin-bottom:18px;background:var(--portal-surface, #191919)}.kpis article{padding:20px;border-right:1px solid var(--portal-line, #333);min-width:0}.kpis article:last-child{border:0}.kpis article>div{display:flex;justify-content:space-between;gap:8px;color:var(--portal-muted, #aaa);font-size:11px}.kpis small{color:var(--portal-muted, #777);font-size:9px}.kpis strong{display:block;font-size:30px;font-weight:500;letter-spacing:-.7px;margin:15px 0 8px}.kpis p{font-size:10px}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,1fr);gap:18px}.panel{border:1px solid var(--portal-line, #303030);border-radius:8px;background:var(--portal-surface, #191919);min-width:0;overflow:hidden}.panel>header{padding:18px 20px;display:flex;align-items:center;justify-content:space-between;gap:15px;border-bottom:1px solid var(--portal-line, #2b2b2b)}.panel>header p{font-size:10px;margin-top:4px}.source-badge,.count{font-size:9px;white-space:nowrap;color:var(--portal-muted, #aaa);border:1px solid var(--portal-line, #3b3b3b);border-radius:99px;padding:3px 8px;display:inline-block;background:var(--portal-raised, #232323)}.empty-chart{min-height:245px;padding:30px 24px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:12px}.empty-chart>.iconify{font-size:25px;color:var(--portal-muted, #777)}.empty-chart p{max-width:360px}.empty-chart h3{color:var(--portal-text, #bbb);font-size:13px}.empty-small{padding:28px 20px;color:var(--portal-muted, #888);display:flex;flex-direction:column;align-items:flex-start;gap:14px;min-height:120px}.empty-small>.iconify{font-size:24px;color:var(--portal-muted, #777)}.bar-list{padding:10px 20px 20px}.bar-list>div{margin-top:15px}.bar-list>div>div{display:flex;justify-content:space-between;font-size:11px;color:var(--portal-muted, #aaa)}.bar-list strong{font